const CONTEXT_LENGTH=32;const MAX_ANCHOR_LENGTH=1e3;const MIN_SIGNIFICANT_OVERLAP_LENGTH=5;function countOccurrencesBefore(n,e,t){if(e.length===0){return 0}let c=0;let r=n.indexOf(e);while(r!==-1&&r<t){c++;r=n.indexOf(e,r+1)}return c}export function extractAnchor(n,e,t){const c=n.slice(e,t);return{prefix:n.slice(Math.max(0,e-CONTEXT_LENGTH),e),exact:c,suffix:n.slice(t,Math.min(n.length,t+CONTEXT_LENGTH)),occurrence:countOccurrencesBefore(n,c,e)}}function findAllOccurrences(n,e){const t=[];let c=n.indexOf(e);while(c!==-1){t.push(c);c=n.indexOf(e,c+1)}return t}function sharesSignificantOverlap(n,e){const t=n=>n.toLowerCase().replace(/\s+/g,"");const c=t(n);const r=t(e);for(let n=0;n<=c.length-MIN_SIGNIFICANT_OVERLAP_LENGTH;n++){if(r.includes(c.slice(n,n+MIN_SIGNIFICANT_OVERLAP_LENGTH))){return true}}return false}function locateByBracketing(n,e,t,c){const r=e.length===0?[0]:findAllOccurrences(n,e).map(n=>n+e.length);const i=t.length===0?[n.length]:findAllOccurrences(n,t);let l=null;let o=false;for(const n of r){const e=i.find(e=>e>=n);if(e!==undefined&&e===n){o=true;continue}if(e===undefined||e-n>MAX_ANCHOR_LENGTH){continue}if(l!==null){return null}l=[n,e]}if(l!==null&&o){const[e,t]=l;if(!sharesSignificantOverlap(n.slice(e,t),c)){return null}}return l}export function locateAnchor(n,e){const{exact:t,prefix:c,suffix:r,occurrence:i}=e;if(!t){return null}const l=[];let o=n.indexOf(t);while(o!==-1){l.push(o);o=n.indexOf(t,o+1)}if(l.length===1){const n=l[0];return[n,n+t.length]}if(l.length>1){const e=e=>{const i=e+t.length;const l=n.slice(Math.max(0,e-c.length),e);const o=n.slice(i,i+r.length);return l===c&&o===r};if(l[i]!==undefined&&e(l[i])){const n=l[i];return[n,n+t.length]}const o=l.find(e);if(o!==undefined){return[o,o+t.length]}}return locateByBracketing(n,c,r,t)}export function overlaps(n,e,t){const c=[];for(const r of n){const n=Math.max(e,r.start);const i=Math.min(t,r.end);if(n<i){c.push({segment:r,start:n,end:i})}}return c}